begin(event: PointerEvent<T>, start: (event: PointerEvent<T>) => ResizeSession | null) {
  if (event.button !== 0 || drag) return;
  const session = start(event);
  if (!session) return;
  const axis = session.axis ?? "x";
  try {
    event.currentTarget.setPointerCapture(event.pointerId);
  } catch {
    session.cleanup?.(false);
    return;
  }
  event.preventDefault();
  event.stopPropagation();
  // Leaving the window mid-drag commits where the pointer was.
  const onBlur = () => finish(true);
  window.addEventListener("blur", onBlur);
  const start = positionAlong(axis, event);
  drag = {
    session,
    target: event.currentTarget,
    pointerId: event.pointerId,
    start,
    pending: start,
    width: session.width,
    moved: false,
    frame: null,
    onBlur,
  };
  document.body.style.cursor = axis === "y" ? "row-resize" : "col-resize";
  document.body.style.userSelect = "none";
},
onPointerMove(event: PointerEvent<T>) {
  const active = drag;
  if (!active || active.pointerId !== event.pointerId) return;
  event.preventDefault();
  const position = positionAlong(active.session.axis ?? "x", event);
  active.pending = position;
  if (Math.abs(position - active.start) > 2) active.moved = true;
  if (active.frame !== null) return;
  active.frame = requestAnimationFrame(() => {
    active.frame = null;
    flush();
  });
},

