For the keyboard handlers, define inside component:

```tsx
const resizeStep = 16;
const handleResizeKeyDown = (axis: "x" | "y") => (event: React.KeyboardEvent<HTMLElement>) => {
  if (event.altKey || event.ctrlKey || event.metaKey) return;
  const current = axis === "x" ? (width ?? MODEL_PICKER_DEFAULT_WIDTH) : (height ?? MODEL_PICKER_DEFAULT_HEIGHT);
  const grow = axis === "x"
    ? event.key === "ArrowRight"
    : popupSide === "top" ? event.key === "ArrowUp" : event.key === "ArrowDown";
  const shrink = axis === "x"
    ? event.key === "ArrowLeft"
    : popupSide === "top" ? event.key === "ArrowDown" : event.key === "ArrowUp";
  let next: number | undefined;
  if (grow) next = current + resizeStep;
  else if (shrink) next = current - resizeStep;
  else if (event.key === "Home") next = axis === "x" ? MODEL_PICKER_MIN_WIDTH : MODEL_PICKER_MIN_HEIGHT;
  else if (event.key === "End") next = axis === "x" ? MODEL_PICKER_MAX_WIDTH : MODEL_PICKER_MAX_HEIGHT;
  if (next === undefined) return;
  event.preventDefault();
  event.stopPropagation();
  if (axis === "x") setWidth(next); else setHeight(next);
};
```
