    axis === "x" ? "ArrowLeft" : popupSide === "top" ? "ArrowDown" : "ArrowUp";
  let next: number | undefined;
  if (event.key === growKey) next = current + 16;
  else if (event.key === shrinkKey) next = current - 16;
