it("resizes by dragging its edges, persists the size, and resets on double-click", async () => {
  localStorage.removeItem("t3code.modelPickerWidth");
  localStorage.removeItem("t3code.modelPickerHeight");
  using _storage = {
    [Symbol.dispose]: () => {
      localStorage.removeItem("t3code.modelPickerWidth");
      localStorage.removeItem("t3code.modelPickerHeight");
    },
  };
  const { act } = await import("../../test/render");

  const instanceId = ProviderInstanceId.make("codex");
  const entries = deriveProviderInstanceEntries([
    {
      instanceId,
      driver: ProviderDriverKind.make("codex"),
      enabled: true,
      installed: true,
      version: null,
      status: "ready" as const,
      auth: { status: "authenticated" as const },
      checkedAt: "2026-01-01T00:00:00.000Z",
      models: [
        { slug: "original", name: "Original model", isCustom: false, capabilities: {} },
      ],
      slashCommands: [],
      skills: [],
    },
  ]);
  const options = new Map([
    [instanceId, [{ slug: "original", name: "Original model" }, { slug: "second", name: "Second model" }]],
  ]);

  await using screen = await render(
    <ProviderModelPicker
      environmentId={null}
      activeInstanceId={instanceId}
      model="original"
      lockedProvider={null}
      instanceEntries={entries}
      modelOptionsByInstance={options}
      triggerAriaLabel="Choose model"
      onInstanceModelChange={() => {}}
    />,
  );
  await screen.getByRole("button", { name: "Choose model" }).click();
  const popup = document.querySelector<HTMLElement>('[data-slot="popover-popup"]')!;
  const initialWidth = popup.getBoundingClientRect().width;
  const initialHeight = popup.getBoundingClientRect().height;

  const fire = (type: string, x: number, y: number) =>
    new PointerEvent(type, {
      bubbles: true,
      cancelable: true,
      pointerId: 1,
      isPrimary: true,
      button: 0,
      buttons: type === "pointerup" ? 0 : 1,
      clientX: x,
      clientY: y,
    });

  const widthHandle = page.getByRole("separator", { name: "Resize model picker width" });
  const widthBounds = widthHandle.element().getBoundingClientRect();
  const widthStart = widthBounds.left + widthBounds.width / 2;
  const widthY = widthBounds.top + widthBounds.height / 2;
  await act(() => {
    widthHandle.element().dispatchEvent(fire("pointerdown", widthStart, widthY));
    widthHandle.element().dispatchEvent(fire("pointermove", widthStart + 80, widthY));
  });
  await vi.waitFor(() => {
    expect(popup.getBoundingClientRect().width).toBeGreaterThan(initialWidth + 40);
  });
  await act(() => {
    widthHandle.element().dispatchEvent(fire("pointerup", widthStart + 80, widthY));
  });
  expect(Number(localStorage.getItem("t3code.modelPickerWidth"))).toBeGreaterThan(initialWidth + 40);

  const heightHandle = page.getByRole("separator", { name: "Resize model picker height" });
  const heightBounds = heightHandle.element().getBoundingClientRect();
  const heightX = heightBounds.left + heightBounds.width / 2;
  const heightStart = heightBounds.top + heightBounds.height / 2;
  await act(() => {
    heightHandle.element().dispatchEvent(fire("pointerdown", heightX, heightStart));
    heightHandle.element().dispatchEvent(fire("pointermove", heightX, heightStart + 60));
  });
  await vi.waitFor(() => {
    expect(popup.getBoundingClientRect().height).toBeGreaterThan(initialHeight + 30);
  });
  await act(() => {
    heightHandle.element().dispatchEvent(fire("pointerup", heightX, heightStart + 60));
  });
  expect(Number(localStorage.getItem("t3code.modelPickerHeight"))).toBeGreaterThan(
    initialHeight + 30,
  );

  focusOptionWidth: {
    widthHandle.element().focus();
    await userEvent.keyboard("{ArrowRight}{ArrowRight}");
    const stored = Number(localStorage.getItem("t3code.modelPickerWidth"));
    const before = popup.getBoundingClientRect().width;
    expect(before).toBeGreaterThanOrEqual(stored - 1);
  }

  await userEvent.dblClick(widthHandle);
  expect(localStorage.getItem("t3code.modelPickerWidth")).toBeNull();
});

